//@title Timeline test 1
//@by stretch___beatz

// Timeline is an underdocumented and under explored function, I think there
// are a lot of possibilities for live use ! Like switching/transitioning 
// between song parts, or doing 'drops'.

// Here's a basic example! First here's a couple of simple extra functions

// 'open' is a continuous signal that goes from 0 to 1 and then stays 
// on 1 forever
const open = signal(t => Math.min(t, 1));

// 'close' is similar but goes from 1 to 0 and stays on 0
const close = signal(t => Math.max(1 - t, 0));


// Switching between timelines. The first time you switch to a timeline it
// starts from cycle 0, but then doesn't reset. Here's a pattern with a
// filter that opens over four cycles. Try switching from timeline 1 to 2
// and back:
$: sound("bd*32")
  .hpf(open.range(100, 10000).slow(4))
  .timeline("1 2 -2 1 2 -1".slow(8))

$: "c3 eb3 g3".when("<0 1>/2", x=>x.sub("5")).note()
// Notice that when you switch back, the timeline _doesn't_ reset. It's as
// though it carried on in the background.

// Now try switching between timeline 1 and -1 . When you change a number
// from positive to negative it resets back to cycle 0. So you don't have 
// to keep switching to a new timeline to reset to cycle 0.
// (It 'quantizes' to the nearest cycle, so that things stay in time.)
